/* =========================================================
   components/about/CulturePageContent.tsx
   恒永达官网｜关于我们 / 恒永达文化统一内容组件

   说明：
   1. 这个组件用于 /about/culture 和 /en/about/culture 等多语言页面
   2. 页面结构沿用原 app/about/culture/page.tsx 的 className
   3. 这样可以继续使用 app/globals.css 里已经调好的企业文化页面样式
   4. 文案和图片路径来自 data/about-culture.ts
========================================================= */

import Image from "next/image";
import SiteBreadcrumb from "@/components/common/SiteBreadcrumb";
import {
  aboutCulturePageText,
  brandActionItems,
  cultureCoreItems,
  cultureProjectItems,
  getCultureText,
  type AboutCultureLocale,
} from "@/data/about-culture";

/* ================================
   组件参数类型
================================ */
type CulturePageContentProps = {
  locale: AboutCultureLocale;
};

/* ================================
   根据当前语言生成链接
   说明：
   1. 中文默认不加语言前缀
   2. 英文、西语、法语、韩语、俄语自动加语言前缀
================================ */
function getLocalizedHref(locale: AboutCultureLocale, href: string) {
  if (locale === "zh-CN") {
    return href;
  }

  if (href === "/") {
    return `/${locale}`;
  }

  return `/${locale}${href}`;
}

