export default function CulturePageContent({ locale }: CulturePageContentProps) {
  return (
    <main className="about-culture-page">
      {/* ================================
          Banner 区域
          说明：
          className 沿用原页面 about-culture-banner
      ================================ */}
      <section
        className="about-culture-banner"
        aria-label={getCultureText(aboutCulturePageText.bannerTitle, locale)}
      >
        <div className="about-culture-container about-culture-banner-inner">
          <h1>{getCultureText(aboutCulturePageText.bannerTitle, locale)}</h1>
          <p>{getCultureText(aboutCulturePageText.bannerDesc, locale)}</p>
        </div>
      </section>

      {/* ================================
          面包屑
          说明：
          沿用原页面 about-culture-breadcrumb 样式
      ================================ */}
      <SiteBreadcrumb
        className="about-culture-breadcrumb"
        items={[
          { label: getCultureText(aboutCulturePageText.breadcrumbHome, locale), href: getLocalizedHref(locale, "/") },
          { label: getCultureText(aboutCulturePageText.breadcrumbAbout, locale), href: getLocalizedHref(locale, "/about/foreach") },
          { label: getCultureText(aboutCulturePageText.sectionTitle, locale) },
        ]}
      />

      {/* ================================
          页面标题
      ================================ */}
      <section className="about-culture-section-title">
        <h2>{getCultureText(aboutCulturePageText.sectionTitle, locale)}</h2>
        <i aria-hidden="true" />
      </section>

      {/* ================================
          恒永达文化核心
          说明：
          沿用原页面：
          about-culture-core-section
          about-culture-core-list
          about-culture-core-item
      ================================ */}
      <section className="about-culture-core-section">
        <div className="about-culture-container">
          <ul className="about-culture-core-list">
            {cultureCoreItems.map((item) => (
              <li
                className="about-culture-core-item"
                key={getCultureText(item.title, locale)}
              >
                <div className="about-culture-core-icon" aria-hidden="true">
                  <CultureCoreIcon icon={item.icon} />
                </div>

                <h3>{getCultureText(item.title, locale)}</h3>
                <p>{getCultureText(item.description, locale)}</p>
              </li>
            ))}
          </ul>
        </div>
      </section>

      {/* ================================
          组织文化横幅
          说明：
          沿用原页面 about-culture-organization-hero
      ================================ */}
      <section
        className="about-culture-organization-hero"
        aria-label={getCultureText(
          aboutCulturePageText.organizationTitle,
          locale,
        )}
      >
        <div className="about-culture-organization-content">
          <h2>
            {getCultureText(aboutCulturePageText.organizationTitle, locale)}
          </h2>
          <p>{getCultureText(aboutCulturePageText.organizationDesc, locale)}</p>
        </div>
      </section>

      {/* ================================
          爱心品牌 / 健康品牌
          说明：
          1. 沿用原页面 about-culture-brand-layout
          2. 图片使用 width / height，不使用 fill，避免样式错乱
          3. 第一张图加 loading eager，处理 LCP 提示
      ================================ */}
      <section className="about-culture-brand-section">
        <div className="about-culture-container about-culture-brand-layout">
          {brandActionItems.map((item, index) => (
            <article
              className={
                item.reverse
                  ? "about-culture-brand-row about-culture-brand-row-reverse"
                  : "about-culture-brand-row"
              }
              key={getCultureText(item.title, locale)}
            >
              <div className="about-culture-brand-text">
                <h3>{getCultureText(item.title, locale)}</h3>
                <p>{getCultureText(item.description, locale)}</p>
              </div>

              <div className="about-culture-brand-image">
                <Image
                  src={item.imageSrc}
                  alt={getCultureText(item.imageAlt, locale)}
                  width={900}
                  height={520}
                  sizes="(max-width: 900px) 100vw, 50vw"
                  loading={index === 0 ? "eager" : "lazy"}
                />
              </div>
            </article>
          ))}
        </div>
      </section>

      {/* ================================
          三大工程
          说明：
          沿用原页面：
          about-culture-project-title
          about-culture-project-list
          about-culture-project-card
      ================================ */}
      <section className="about-culture-project-section">
        <div className="about-culture-container">
          <div className="about-culture-project-title">
            <h2>
              {getCultureText(aboutCulturePageText.projectMainTitle, locale)}
            </h2>
            <i aria-hidden="true" />
            <p>
              {getCultureText(aboutCulturePageText.projectMainDesc, locale)}
            </p>
          </div>

          <div className="about-culture-project-list">
            {cultureProjectItems.map((item) => (
              <article
                className="about-culture-project-card"
                key={getCultureText(item.title, locale)}
              >
                <div className="about-culture-project-image">
                  <Image
                    src={item.imageSrc}
                    alt={getCultureText(item.imageAlt, locale)}
                    width={680}
                    height={420}
                    sizes="(max-width: 900px) 100vw, 33vw"
                  />
                </div>

                <div className="about-culture-project-content">
                  <h3>{getCultureText(item.title, locale)}</h3>
                  <p>{getCultureText(item.description, locale)}</p>
                </div>
              </article>
            ))}
          </div>
        </div>
      </section>
    </main>
  );
}
